// === Tab: mySketch ===
// Rainbow Tiles

// A simple contribution to #WCCChallenge 'Pride' as well as a sketch for #tilingtuesday.
// Click or tap into the field and the tiles' colour patterns change (depending o the distance to
// the pointer).

// There is a fork of this sketch (Rainbow Tiles II) offering far mor color values between red and violet; 
// you can check it out on Openprocessing, too, but it might be not that corresponding to the 'Pride' topic.


// Storing the settings
var cfg = {
	rowCols: 6,	
	len: 0,
	hexs: [], 
	clr: []
}

class Hex {
	constructor(i, j) {
		this.i = i;
		this.j = j;
		this.stage = floor(random() * 6);
		//Centre coordinates
		this.x = cfg.len * (3 * this.i + 1.5 * (this.j % 2));
		this.y = this.j * cfg.len * sqrt(0.75);
	}

	show() {
		stroke(0);
		strokeWeight(cfg.len*0.025);
		noFill();
		beginShape();

		// The concentric hex lines are actually bordered hex shapes of decreasing size, each with anothe fill colour.
		for (let n = 0; n < 6; n++) {
			beginShape();
			// The colour varies with the stage attribute which is changed in toggle()
			fill(cfg.clrs[(n + this.stage) % 6]);
			for (var k = 0; k < 6; k++) {
				let phi = PI *  (k - 2) / 3;
				let r = map(n, 0, 6, cfg.len, 0);
				let x = this.x + r * cos(phi);
				let y = this.y + r * sin(phi);
				vertex(x,y);
			}
			endShape(CLOSE);
		}
	}
	// Calling this method changes the colour pattern.
	toggle(val) {
		this.stage = val % 6;
	}
}

function setup() {
	// making a square canvas and setting the hexagons' size.
	var a = max(windowWidth, windowHeight);
	createCanvas(a,a);		
	cfg.len = a / (2.75 * cfg.rowCols);
	// The colour set of the pride flag.
	cfg.clrs = [color(230,0,0), color(255,140,0), color(255,240,0), color(0,130,30), color(0,70,255), color(125,0,140)];
	// Initialising the hexagons and storing them in the hexs set definied in cfg (see above).
	for (let j = 0; j < cfg.rowCols * 3 + 3; j++) {
		for (let i = 0; i < cfg.rowCols; i++) {
			cfg.hexs.push(new Hex(i,j));
		}
	}
}

function mouseClicked() {
	// Each hex is toggled by the distances to the  pointer
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) >=0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) <= width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) >= 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) <= height) {
		//Getting the pointer's row and col
		let hrow = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / (cfg.len * sqrt(0.75));
		let hrow_ = round(hrow);
		let dcol = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / (1.5 * cfg.len);
		let dcol_ = floor(round(dcol) / 2);
		let n = cfg.rowCols * hrow_ + dcol_;
		// toggling the hexagons
		for (let h of cfg.hexs) {
			let dist = sqrt((dcol_ - h.i) ** 2 + (hrow - h.j) ** 2);
			let val = round(map(dist, 0, 10, 0, 5)) % 6;
			h.toggle(val);
		}
	}
}

function draw() {
	frameRate(10);
	background(220);
	for (h of cfg.hexs) {
		h.show();
	}
}
